import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M12.5 1a1 1 0 1 1 0 2h-1.831a1 1 0 0 0-.983.821L9.335 6H11a1 1 0 1 1 0 2H9.013l-.727 4.517-.004.02A3 3 0 0 1 5.332 15H4a1 1 0 1 1 0-2h1.331a1 1 0 0 0 .983-.821L6.987 8H5a1 1 0 0 1 0-2h2.309l.405-2.517.004-.02a3 3 0 0 1 2.95-2.462z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M15 2a1 1 0 1 1 0 2h-2.038a1.5 1.5 0 0 0-1.477 1.227h.001L10.996 8h3.083a1 1 0 0 1 0 2h-3.438l-.908 5.121v.005a3.5 3.5 0 0 1-3.14 2.86L6.289 18H4a1 1 0 1 1 0-2h2.288a1.5 1.5 0 0 0 1.477-1.231L8.609 10H5a1 1 0 0 1 0-2h3.964l.553-3.121v-.005A3.5 3.5 0 0 1 12.963 2z"] as readonly string[];

export const FunctionMinimalIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="function-minimal" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
FunctionMinimalIcon.displayName = `Blueprint6.Icon.FunctionMinimalIcon`;

/**
 * @deprecated Use {@link FunctionMinimalIcon} instead.
 */
export const FunctionMinimal: typeof FunctionMinimalIcon = FunctionMinimalIcon;

export default FunctionMinimalIcon;
